import json,glob,sys,hashlib;from collections import defaultdict;sp=lambda i:("train" if (v:=int(hashlib.sha256(i.encode()).hexdigest()[:8],16)%20)<16 else ("val" if v<18 else "test"));recs=[(s["id"],s.get("image_sha256"),s.get("split")) for s in json.load(open("data/synthetic/index.json"))["samples"]];recs+=[(o["id"],o.get("image_sha256"),o.get("split")) for f in glob.glob("data/exports/*.jsonl") for o in map(json.loads,filter(None,open(f,encoding="utf-8").read().splitlines()))];mism=[r[0] for r in recs if r[2] is not None and r[2]!=sp(r[0])];sets={k:{r[0] for r in recs if sp(r[0])==k} for k in ("train","val","test")};pairs=[(a,b) for a in sets for b in sets if a<b and sets[a]&sets[b]];m=defaultdict(set);[m[r[1]].add(sp(r[0])) for r in recs if r[1]];cross=[s for s,ks in m.items() if len(ks)>1];leak=len(mism)+len(pairs)+len(cross);print("n=%d stored_mismatch=%d pair_overlap=%d sha_cross=%d leak=%d"%(len(recs),len(mism),len(pairs),len(cross),leak));sys.exit(0 if leak==0 and recs else 1)